"use client"

import type { CSSProperties, ReactNode } from "react"

import Shell from "@/components/ui/shell"
import { cn } from "@/lib/utils"

import { SHELL_HEADER_HEIGHT } from "./shell-constants"

export type AuthSplitShellProps = {
	children: ReactNode
	aside?: ReactNode
	className?: string
}

/**
 * Split view for auth/marketing: form column + optional visual aside.
 * Pair with `AuthCardLayout` from `auth` in the main column.
 */
export function AuthSplitShell({ children, aside, className }: AuthSplitShellProps) {
	return (
		<Shell.Frame
			className={cn("min-h-[min(720px,75vh)]", className)}
			style={{ "--shell-header-height": SHELL_HEADER_HEIGHT } as CSSProperties}>
			<div className="grid min-h-0 flex-1 grid-cols-1 md:grid-cols-2">
				<Shell.Section className="flex items-center justify-center p-4 md:p-8" variant="center">
					<div className="w-full max-w-md">{children}</div>
				</Shell.Section>
				{aside ? (
					<div className="hidden border-l bg-muted/30 md:block">{aside}</div>
				) : (
					<div
						aria-hidden
						className="hidden border-l bg-[radial-gradient(ellipse_at_top,--theme(--color-primary/.12),transparent_55%)] md:block"
					/>
				)}
			</div>
		</Shell.Frame>
	)
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

export type ContentPageHeaderProps = {
	title: string
	description?: string
	actions?: ReactNode
	className?: string
}

export function ContentPageHeader({ title, description, actions, className }: ContentPageHeaderProps) {
	return (
		<div className={cn("flex flex-col gap-3 border-b pb-4 sm:flex-row sm:items-start sm:justify-between", className)}>
			<div className="min-w-0 space-y-1">
				<h2 className="font-semibold text-xl tracking-tight">{title}</h2>
				{description ? <p className="text-muted-foreground text-sm">{description}</p> : null}
			</div>
			{actions ? <div className="flex shrink-0 items-center gap-2">{actions}</div> : null}
		</div>
	)
}

"use client"

import type { ReactNode } from "react"

import Shell from "@/components/ui/shell"
import { Separator } from "@/components/ui/separator"
import { SidebarTrigger } from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

import { Breadcrumbs } from "../breadcrumb"
import { SHELL_HEADER_HEIGHT_CLASS } from "./shell-constants"

export function DashboardHeader({
	actions,
	className,
	showBreadcrumbs = true,
	showSidebarTrigger = true,
}: {
	actions?: ReactNode
	className?: string
	showBreadcrumbs?: boolean
	showSidebarTrigger?: boolean
}) {
	return (
		<Shell.Header className={cn(SHELL_HEADER_HEIGHT_CLASS, "flex items-center gap-2 px-4", className)} variant="app">
			{showSidebarTrigger ? <SidebarTrigger className="-ms-1" /> : null}
			{showSidebarTrigger ? <Separator className="mr-2 h-4" orientation="vertical" /> : null}
			{showBreadcrumbs ? <Breadcrumbs className="min-w-0 flex-1" /> : <div className="flex-1" />}
			{actions ? <div className="flex shrink-0 items-center gap-2">{actions}</div> : null}
		</Shell.Header>
	)
}

"use client"

import type { LucideIcon } from "lucide-react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import type { ReactNode } from "react"

import { SidebarFlatNavGroup } from "@/components/ui/sidebar-flat-nav-group"
import {
	SidebarGroup,
	SidebarGroupContent,
	SidebarGroupLabel,
	SidebarMenu,
	SidebarMenuButton,
	SidebarMenuItem,
	SidebarMenuSubButton,
	SidebarMenuSubItem,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

export type DashboardNavItem = {
	title: string
	href: string
	icon?: LucideIcon
}

export type DashboardNavGroup = {
	label: string
	icon?: LucideIcon
	defaultOpen?: boolean
	items: DashboardNavItem[]
}

export type DashboardNavLink = DashboardNavItem

export function DashboardSidebarNav({
	groups,
	links,
	className,
}: {
	groups?: DashboardNavGroup[]
	links?: DashboardNavLink[]
	className?: string
}) {
	const pathname = usePathname()

	return (
		<div className={cn("flex flex-col gap-2", className)}>
			{links?.length ? (
				<SidebarGroup>
					<SidebarGroupContent>
						<SidebarMenu>
							{links.map((link) => {
								const Icon = link.icon
								const active = pathname === link.href || pathname.startsWith(`${link.href}/`)
								return (
									<SidebarMenuItem key={link.href}>
										<SidebarMenuButton asChild isActive={active} tooltip={link.title}>
											<Link href={link.href}>
												{Icon ? <Icon /> : null}
												<span>{link.title}</span>
											</Link>
										</SidebarMenuButton>
									</SidebarMenuItem>
								)
							})}
						</SidebarMenu>
					</SidebarGroupContent>
				</SidebarGroup>
			) : null}
			{groups?.map((group) => {
				const GroupIcon = group.icon
				return (
					<SidebarGroup key={group.label}>
						<SidebarGroupLabel className="sr-only">{group.label}</SidebarGroupLabel>
						<SidebarGroupContent>
							<SidebarFlatNavGroup
								{...(group.defaultOpen !== undefined ? { defaultOpen: group.defaultOpen } : {})}
								{...(GroupIcon ? { icon: <GroupIcon /> } : {})}
								label={group.label}>
								{group.items.map((item) => {
									const ItemIcon = item.icon
									const active = pathname === item.href || pathname.startsWith(`${item.href}/`)
									return (
										<SidebarMenuSubItem key={item.href}>
											<SidebarMenuSubButton asChild isActive={active}>
												<Link href={item.href}>
													{ItemIcon ? <ItemIcon className="size-4" /> : null}
													<span>{item.title}</span>
												</Link>
											</SidebarMenuSubButton>
										</SidebarMenuSubItem>
									)
								})}
							</SidebarFlatNavGroup>
						</SidebarGroupContent>
					</SidebarGroup>
				)
			})}
		</div>
	)
}

export function DashboardSidebarBrand({
	title,
	subtitle,
	href,
	logo,
}: {
	title: string
	subtitle?: string
	href: string
	logo?: ReactNode
}) {
	return (
		<SidebarMenu>
			<SidebarMenuItem>
				<SidebarMenuButton asChild className="group" size="lg">
					<Link href={href}>
						{logo}
						<div className="grid flex-1 text-left text-sm leading-tight">
							<span className="truncate font-semibold">{title}</span>
							{subtitle ? (
								<span className="truncate text-muted-foreground text-xs">{subtitle}</span>
							) : null}
						</div>
					</Link>
				</SidebarMenuButton>
			</SidebarMenuItem>
		</SidebarMenu>
	)
}

import {
	SidebarGroup,
	SidebarGroupContent,
	SidebarGroupLabel,
	SidebarMenu,
	SidebarMenuItem,
	SidebarMenuSkeleton,
} from "@/components/ui/sidebar"

export function DashboardSidebarNavSkeleton({ groups = 2 }: { groups?: number }) {
	return (
		<>
			{Array.from({ length: groups }).map((_, groupIndex) => (
				<SidebarGroup key={groupIndex}>
					<SidebarGroupLabel>
						<span className="sr-only">Loading navigation</span>
					</SidebarGroupLabel>
					<SidebarGroupContent>
						<SidebarMenu>
							{Array.from({ length: 3 }).map((__, itemIndex) => (
								<SidebarMenuItem key={itemIndex}>
									<SidebarMenuSkeleton showIcon />
								</SidebarMenuItem>
							))}
						</SidebarMenu>
					</SidebarGroupContent>
				</SidebarGroup>
			))}
		</>
	)
}

"use client"

import type { LucideIcon } from "lucide-react"
import Link from "next/link"
import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

export type SettingsNavItem = {
	id: string
	title: string
	href: string
	icon?: LucideIcon
	description?: string
}

export type SettingsLayoutProps = {
	title: string
	description?: string
	navigation: SettingsNavItem[]
	activeId: string
	children: ReactNode
	className?: string
}

/** In-content secondary navigation for settings-style pages (profile, billing, security). */
export function SettingsLayout({
	title,
	description,
	navigation,
	activeId,
	children,
	className,
}: SettingsLayoutProps) {
	return (
		<div className={cn("flex min-h-0 flex-1 flex-col gap-6 lg:flex-row lg:gap-10", className)}>
			<aside className="w-full shrink-0 lg:w-56">
				<div className="mb-4 lg:mb-6">
					<h1 className="font-semibold text-2xl tracking-tight">{title}</h1>
					{description ? <p className="mt-1 text-muted-foreground text-sm">{description}</p> : null}
				</div>
				<nav aria-label="Settings" className="flex flex-col gap-1">
					{navigation.map((item) => {
						const Icon = item.icon
						const active = item.id === activeId
						return (
							<Link
								key={item.id}
								className={cn(
									"flex items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors",
									active
										? "bg-muted font-medium text-foreground"
										: "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
								)}
								href={item.href}>
								{Icon ? <Icon className="size-4 shrink-0" /> : null}
								<span>{item.title}</span>
							</Link>
						)
					})}
				</nav>
			</aside>
			<div className="min-w-0 flex-1">{children}</div>
		</div>
	)
}

/** Matches `Shell.Header` `app` variant (`h-12`). */
export const SHELL_HEADER_HEIGHT = "3rem"
export const SHELL_HEADER_HEIGHT_CLASS = "h-12"

"use client"

import type { CSSProperties, ReactNode } from "react"

import Shell from "@/components/ui/shell"
import { SHELL_HEADER_HEIGHT } from "./shell-constants"
import { DashboardHeader } from "./dashboard-header"

export type TopNavShellProps = {
	children: ReactNode
	headerActions?: ReactNode
	topNavigation?: ReactNode
	className?: string
	showBreadcrumbs?: boolean
}

/** Header + main content without a sidebar — use for marketing-style app shells or narrow tools. */
export function TopNavShell({
	children,
	headerActions,
	topNavigation,
	className,
	showBreadcrumbs = true,
}: TopNavShellProps) {
	return (
		<Shell.Frame
			{...(className ? { className } : {})}
			style={{ "--shell-header-height": SHELL_HEADER_HEIGHT } as CSSProperties}>
			<DashboardHeader
				actions={headerActions}
				showBreadcrumbs={showBreadcrumbs}
				showSidebarTrigger={false}
			/>
			{topNavigation ? (
				<div className="border-b bg-background px-4 py-2 md:px-6">{topNavigation}</div>
			) : null}
			<Shell.Main className="min-h-0 flex-1 overflow-hidden" variant="dashboard">
				<Shell.Section className="p-4 md:p-6" variant="dashboard">
					{children}
				</Shell.Section>
			</Shell.Main>
		</Shell.Frame>
	)
}
